const raw = String($input.first().json.text || "").trim();
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");
if (start === -1 || end <= start) {
  throw new Error("Onboarding Agent: model did not return a JSON object");
}
let data;
try {
  data = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error("Onboarding Agent: model returned invalid JSON");
}
const summary = typeof data.welcomeSummary === "string" ? data.welcomeSummary.trim() : "";
const steps = Array.isArray(data.onboardingSteps)
  ? data.onboardingSteps.filter((s) => typeof s === "string" && s.trim()).map((s) => s.trim())
  : [];
if (!summary || steps.length < 3) {
  throw new Error("Onboarding Agent: output failed schema validation");
}
return [{ json: {
  welcomeSummary: summary.slice(0, 500),
  onboardingSteps: steps.slice(0, 6).map((s) => s.slice(0, 250))
} }];
